<script setup>
import {ref,watch,onMounted,computed} from 'vue';import {Head,Link,router,usePage} from '@inertiajs/vue3';import Feedback from '../Components/Feedback.vue';import {crew,message} from '../art';import axios from 'axios';
const props=defineProps({questions:Object,catalog:Object,filters:Object,bookmarks:Array}),page=usePage();
const search=ref(props.filters.search||''),subject=ref(props.filters.subject||''),view=ref(props.filters.view||(props.filters.bookmarks?'bookmarks':'all')),open=ref({}),answers=ref({}),tray=ref([]),busy=ref(false),error=ref('');
const storageKey='sushi-tray-'+page.props.user.id;
onMounted(()=>{try{const saved=JSON.parse(sessionStorage.getItem(storageKey)||'[]');if(Array.isArray(saved))tray.value=saved.filter(id=>typeof id==='string').slice(0,500)}catch{}});
watch(tray,()=>{try{sessionStorage.setItem(storageKey,JSON.stringify(tray.value))}catch{}},{deep:true});
function filter(){router.get('/library',{search:search.value,subject:subject.value,view:view.value},{preserveState:true,preserveScroll:true})}
function select(id){if(tray.value.includes(id))tray.value=tray.value.filter(x=>x!==id);else if(tray.value.length<500)tray.value=[...tray.value,id];else error.value='Your tray can hold up to 500 questions.'}
async function reveal(q){answers.value[q.id]=!answers.value[q.id];if(answers.value[q.id]){try{const r=await axios.post('/questions/'+q.id+'/view',{mode:'library'});page.props.community=r.data.community}catch(e){error.value=message(e)}}}
function start(mode){busy.value=true;error.value='';router.post('/library/study',{mode,selected_ids:tray.value},{preserveScroll:true,onError:e=>error.value=Object.values(e).join(' '),onFinish:()=>busy.value=false})}
</script>
<template><Head title="Roll Call"/><div class="page-title"><div><p class="eyebrow">Find your next study set</p><h1>Roll Call</h1><p>Browse, save, or place exact questions in your study tray.</p></div><img class="portrait" :src="'/art/nori-librarian.png'" alt="Nori Librarian"></div>
<form class="library-search" @submit.prevent="filter"><label>Search questions<input v-model="search" placeholder="Search a question, topic, or ID"></label><label>Subject<select v-model="subject" @change="filter"><option value="">All subjects</option><option v-for="s in catalog.subjects" :key="s">{{s}}</option></select></label><button class="primary">Search</button></form>
<div class="library-tools"><div class="segmented"><button v-for="[id,label] in [['all','All'],['new','Unseen'],['missed','Missed'],['bookmarks','Saved']]" :key="id" :class="{selected:view===id}" @click="view=id;filter()">{{label}}</button></div><small>{{questions.total}} questions found</small></div>
<p v-if="error" class="notice error" role="alert">{{error}}</p>
<article v-for="q in questions.data" :key="q.id" class="panel library-row"><p class="library-meta">{{q.id}} · {{q.subject}} · {{q.topic}} · {{q.tier}}</p><h2 class="pre" :class="{'library-preview':!open[q.id]}">{{q.stem}}</h2>
<template v-if="open[q.id]"><p v-for="(option,i) in q.options" :key="i">{{String.fromCharCode(65+i)}}. {{option}}</p></template>
<div class="library-actions"><button :aria-expanded="!!open[q.id]" @click="open[q.id]=!open[q.id]">{{open[q.id]?'Collapse':'Open question'}}</button><button v-if="open[q.id]" :aria-expanded="!!answers[q.id]" @click="reveal(q)">{{answers[q.id]?'Hide answer':'Reveal answer'}}</button><button @click="router.post('/bookmarks/'+q.id,{bookmarked:!bookmarks.includes(q.id)},{preserveScroll:true,preserveState:true})">{{bookmarks.includes(q.id)?'★ Saved':'☆ Save'}}</button><button :class="{selected:tray.includes(q.id)}" :aria-pressed="tray.includes(q.id)" @click="select(q.id)">{{tray.includes(q.id)?'✓ In tray':'+ Study tray'}}</button></div>
<Feedback v-if="open[q.id]&&answers[q.id]" :question="q"/></article><p v-if="!questions.data.length" class="panel">No questions match. Try another subject or view.</p>
<div class="row"><Link v-if="questions.prev_page_url" :href="questions.prev_page_url" class="button" preserve-state preserve-scroll>Previous</Link><span>Page {{questions.current_page}} of {{questions.last_page}}</span><Link v-if="questions.next_page_url" :href="questions.next_page_url" class="button" preserve-state preserve-scroll>Next</Link></div>
<aside v-if="tray.length" class="study-tray"><div class="row"><div><strong>Your study tray · {{tray.length}}</strong><small>Only these questions enter your round.</small></div><div class="row"><button :disabled="busy" @click="start('memory')">Memory Maki</button><button class="primary" :disabled="busy" @click="start('tutor')">Maki Mentor</button></div></div><details><summary>Review selected questions</summary><div class="tray-items"><button v-for="id in tray" :key="id" @click="select(id)">{{id}} ×</button><button class="plain" @click="tray=[]">Clear tray</button></div></details></aside></template>
